def _parse_ascii_tformat(tform, strict=False):
    """Parse an ASCII-table TFORM value into format, width, precision."""
    text = tform.strip()
    match = TFORMAT_ASCII_RE.fullmatch(text)
    if match is None:
        raise VerifyError(f"Format {tform!r} is not recognized.")

    format_code = (match.group("format") or match.group("formatf")).upper()
    width_text = match.group("width") or match.group("widthf")
    precision_text = match.group("precision")
    floating = format_code in ("E", "F", "D")

    if width_text is None:
        if strict:
            raise VerifyError(f"Format {tform!r} is ambiguous.")
        width, precision = ASCII_DEFAULT_WIDTHS[format_code]
    else:
        width = int(width_text)
        if floating and precision_text is None and strict:
            raise VerifyError(f"Format {tform!r} is ambiguous.")
        precision = int(precision_text) if precision_text is not None else 0

    if width <= 0:
        raise VerifyError("ASCII table column width must be a positive integer.")
    if precision >= width:
        raise VerifyError(
            "ASCII table column precision must be less than the column width."
        )

    return format_code, width, precision


